pub async fn h(user: AuthUser, Path(id): Path<i64>, Query(q): Query<Opts>) -> Result<Json<Note>, StatusCode> {
    let conn = &mut pool();
    let mut query = notes::table.find(id).filter(notes::owner.eq(&user.id)).into_boxed();
