use axum::{extract::{Extension, Path, State}, http::StatusCode, Json};
use sqlx::PgPool;

use crate::auth::{AuthUser, HeaderAuth, TokenUser};
use crate::models::{Note, Tag, User};
use crate::store::NOTES;
use crate::schema::notes;
use crate::entity::note;
use crate::models::Bulk;

pub async fn h(user: AuthUser, Path(id): Path<i64>, Json(q): Json<Bulk>) -> Result<StatusCode, StatusCode> {
    let note = NOTES.find(id).ok_or(StatusCode::NOT_FOUND)?;
    if note.owner != user.id {
        return Err(StatusCode::FORBIDDEN);
    }
    q.also.into_iter().for_each(|id| { NOTES.remove(id); });
    Ok(StatusCode::NO_CONTENT)
}

