    pub on_behalf_of: String,
}

impl<S: Send + Sync> FromRequestParts<S> for DelegatedAuthUser {
    type Rejection = StatusCode;

    async fn from_request_parts(parts: &mut Parts, _state: &S) -> Result<Self, Self::Rejection> {
        let me = parts.extensions.get::<AuthUser>().cloned().ok_or(StatusCode::UNAUTHORIZED)?;
        let other = parts.headers.get("x-on-behalf-of").and_then(|v| v.to_str().ok()).map(str::to_string);
        Ok(DelegatedAuthUser { on_behalf_of: other.unwrap_or_else(|| me.id.clone()), id: me.id })
    }
}

