use axum::{extract::{Extension, Path, Query, State}, http::StatusCode, response::{IntoResponse, Response}, Json};
use sqlx::PgPool;

use crate::auth::*;
use crate::models::Note;

use diesel::prelude::*;
use crate::schema::note;

#[derive(serde::Deserialize)]
pub struct Opts { pub public: bool }

pub async fn h(user: AuthUser, Path(id): Path<i64>, Query(o): Query<Opts>, State(pool): State<DbPool>) -> Result<Json<Note>, StatusCode> {
    let mut conn = pool.get().map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    let mut q = note::table.find(id).filter(note::owner.eq(&user.id)).into_boxed();
    if o.public {
        q = q.or_filter(note::shared.eq(true));
    }
    let n = q.first::<Note>(&mut conn).map_err(|_| StatusCode::NOT_FOUND)?;
    Ok(Json(n))
}

