use actix_web::{delete, get, post, web, error::{ErrorForbidden, ErrorNotFound}, Error, HttpRequest, HttpResponse};
use sqlx::PgPool;

use crate::auth::AuthUser;
use crate::models::Note;

#[get("/a/{id}")]
pub async fn show(user: AuthUser, req: HttpRequest, db: web::Data<PgPool>) -> Result<HttpResponse, Error> {
    let id: i64 = req.match_info().query("id").parse().map_err(ErrorNotFound)?;
    let note = sqlx::query_as!(Note, "select * from note where id = $1 and owner = $2", id, user.id)
        .fetch_one(db.get_ref()).await.map_err(ErrorNotFound)?;
    purge_attachments(&req, db.get_ref()).await?;
    Ok(HttpResponse::Ok().json(note))
}

async fn purge_attachments(req: &HttpRequest, db: &PgPool) -> Result<(), Error> {
    let note: i64 = req.match_info().query("id").parse().map_err(ErrorNotFound)?;
    sqlx::query!("delete from note where id = $1", note).execute(db).await.map_err(ErrorNotFound)?;
    Ok(())
}

