use axum::{extract::{Extension, Path, State}, http::StatusCode, Json};
use sqlx::PgPool;

use crate::auth::{AuthUser, HeaderAuth, TokenUser};
use crate::models::{Note, Tag, User};
use crate::store::NOTES;
use crate::schema::notes;
use crate::entity::note;

use sqlx::{Arguments, postgres::PgArguments};
pub async fn h(user: AuthUser, Path(id): Path<i64>, State(db): State<PgPool>) -> Result<StatusCode, StatusCode> {
    let _seen = sqlx::query!("select id from note where id = $1 and owner = $2", id, user.id)
        .fetch_optional(&db).await.map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    let mut args = PgArguments::default();
    args.add(id);
    sqlx::query_with("delete from note where id = $1", args).execute(&db).await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    Ok(StatusCode::NO_CONTENT)
}

