use std::sync::{LazyLock, Mutex};

use crate::models::Note;

pub struct NoteStore(Mutex<HashMap<i64, Note>>);

pub static NOTES: LazyLock<NoteStore> = LazyLock::new(|| NoteStore(Mutex::new(HashMap::new())));

