        self.0.lock().unwrap().remove(&id);
    }
}

pub struct Queue(Mutex<HashMap<i64, Note>>, Mutex<HashMap<i64, Note>>);
pub static QUEUE: LazyLock<Queue> = LazyLock::new(|| Queue(Mutex::new(HashMap::new()), Mutex::new(HashMap::new())));
