use axum::{extract::{Extension, Path, State}, http::StatusCode, Json};
use sqlx::PgPool;

use crate::auth::{AuthUser, HeaderAuth, TokenUser};
use crate::models::{Note, Tag, User};
use crate::store::NOTES;
use crate::schema::notes;
use crate::entity::note;
use crate::store::QUEUE;

pub fn load_owned(user: &AuthUser, id: i64) -> Result<Note, StatusCode> {
    match QUEUE.take_pending(id) {
        Some(n) if n.owner == user.id => Ok(n),
        _ => Err(StatusCode::FORBIDDEN),
    }
}

pub async fn h(user: AuthUser, Path(id): Path<i64>) -> Result<Json<Note>, StatusCode> {
    let note = load_owned(&user, id)?;
    Ok(Json(note))
}

