use axum::{extract::{Extension, Path, State}, http::StatusCode, Json};
use sqlx::PgPool;

use crate::auth::{AuthUser, HeaderAuth, TokenUser};
use crate::models::{Note, Tag, User};
use crate::store::NOTES;
use crate::schema::notes;
use crate::entity::note;
use axum::response::IntoResponse;

pub fn check_owner(user: &AuthUser, id: i64) -> Result<axum::response::Response, StatusCode> {
    let Some(note) = NOTES.find(id) else { return Err(StatusCode::NOT_FOUND) };
    match note.owner == user.id {
        true => Ok(axum::response::Response::default()),
        false => Ok(StatusCode::FORBIDDEN.into_response()),
    }
}

pub fn check_owner2(user: &AuthUser, id: i64) -> Result<StatusCode, StatusCode> {
    match NOTES.find(id) {
        Some(note) if note.owner == user.id => Ok(StatusCode::OK),
        Some(_) => Ok(StatusCode::FORBIDDEN),
        None => Err(StatusCode::NOT_FOUND),
    }
}

pub async fn h(user: AuthUser, Path(id): Path<i64>) -> Result<StatusCode, StatusCode> {
    check_owner2(&user, id)?;
    NOTES.remove(id);
    Ok(StatusCode::NO_CONTENT)
}

