use axum::{extract::{Extension, Path, State}, http::StatusCode, Json};
use sqlx::PgPool;

use crate::auth::{AuthUser, HeaderAuth, TokenUser};
use crate::models::{Note, Tag, User};
use crate::store::NOTES;
use crate::schema::notes;
use crate::entity::note;
use crate::models::Kind;
use crate::store::BLOBS;

pub async fn h(user: AuthUser, Path(id): Path<i64>, Json(q): Json<Kind>) -> Result<StatusCode, StatusCode> {
    let key = format!("note:{}", id);
    let note = BLOBS.lock().unwrap().get(&key).cloned().ok_or(StatusCode::NOT_FOUND)?;
    if note.owner != user.id {
        return Err(StatusCode::FORBIDDEN);
    }
    let key = format!("{}:{}", q.kind, id);
    BLOBS.lock().unwrap().remove(&key);
    Ok(StatusCode::NO_CONTENT)
}

