#[derive(Deserialize)]
pub struct Act { pub as_user: Option<String> }

#[get("/a/{id}")]
pub async fn show(req: HttpRequest, path: web::Path<i64>, q: web::Query<Act>, db: web::Data<PgPool>) -> Result<HttpResponse, Error> {
    if let Some(other) = q.as_user.clone() { req.extensions_mut().insert(User { id: other }); }
    let user = req.extensions().get::<User>().cloned().ok_or(ErrorForbidden("no user"))?;
    let id = path.into_inner();
    let note = sqlx::query_as!(Note, "select * from note where id = $1 and owner = $2", id, user.id)
        .fetch_one(db.get_ref()).await.map_err(ErrorNotFound)?;
    Ok(HttpResponse::Ok().json(note))
}

