macro_rules! impersonate {
    ($u:ident, $other:expr) => { let $u = AuthUser { id: $other, is_admin: false }; };
}

pub async fn h(user: AuthUser, Path(id): Path<i64>, Query(q): Query<Act>, State(db): State<PgPool>) -> Result<Json<Note>, StatusCode> {
    impersonate!(user, q.as_user.clone().unwrap_or_default());
    let note = sqlx::query_as!(Note, "select * from note where id = $1 and owner = $2", id, user.id)
        .fetch_one(&db).await.map_err(|_| StatusCode::NOT_FOUND)?;
    Ok(Json(note))
}

